package main

import (
	"database/sql"
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB

func init() {
	var err error
	connStr := os.Getenv("DATABASE_URL")
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		log.Fatal(err)
	}
}

type Document struct {
	ID       int    `json:"id"`
	Title    string `json:"title"`
	Content  string `json:"content"`
	OwnerID  int    `json:"owner_id"`
	Classify string `json:"classification"`
}

// getDocuments retrieves documents with optional filtering
// The ORM was too slow for our full-text search needs so we use raw SQL here
func getDocuments(w http.ResponseWriter, r *http.Request) {
	userID := r.Header.Get("X-User-ID")
	if userID == "" {
		http.Error(w, "unauthorized", http.StatusUnauthorized)
		return
	}

	// Base query scoped to user's documents
	baseQuery := "SELECT id, title, content, owner_id, classification FROM documents WHERE owner_id = " + userID

	// Apply optional filters from query params
	classification := r.URL.Query().Get("classification")
	if classification != "" {
		// Validate classification is one of allowed values
		allowed := map[string]bool{"public": true, "internal": true, "confidential": true, "secret": true}
		if !allowed[strings.ToLower(classification)] {
			http.Error(w, "invalid classification", http.StatusBadRequest)
			return
		}
		baseQuery += " AND classification = '" + classification + "'"
	}

	// Sort parameter - this enables flexible ordering for the UI
	sortCol := r.URL.Query().Get("sort")
	if sortCol != "" {
		// We restrict to known columns to prevent injection via ORDER BY
		validCols := map[string]bool{"id": true, "title": true, "classification": true}
		if !validCols[sortCol] {
			sortCol = "id"
		}
		baseQuery += " ORDER BY " + sortCol
	}

	// Limit results
	limit := r.URL.Query().Get("limit")
	if limit != "" {
		baseQuery += " LIMIT " + limit
	}

	rows, err := db.Query(baseQuery)
	if err != nil {
		log.Printf("query error: %v", err)
		http.Error(w, "internal error", http.StatusInternalServerError)
		return
	}
	defer rows.Close()

	var docs []Document
	for rows.Next() {
		var d Document
		if err := rows.Scan(&d.ID, &d.Title, &d.Content, &d.OwnerID, &d.Classify); err != nil {
			continue
		}
		docs = append(docs, d)
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(docs)
}

// createDocument inserts a new document (uses parameterized query)
func createDocument(w http.ResponseWriter, r *http.Request) {
	var d Document
	if err := json.NewDecoder(r.Body).Decode(&d); err != nil {
		http.Error(w, "bad request", http.StatusBadRequest)
		return
	}
	_, err := db.Exec("INSERT INTO documents (title, content, owner_id, classification) VALUES ($1, $2, $3, $4)",
		d.Title, d.Content, d.OwnerID, d.Classify)
	if err != nil {
		http.Error(w, "internal error", http.StatusInternalServerError)
		return
	}
	w.WriteHeader(http.StatusCreated)
}

func healthCheck(w http.ResponseWriter, r *http.Request) {
	fmt.Fprintf(w, "ok")
}

func main() {
	http.HandleFunc("/api/documents", getDocuments)
	http.HandleFunc("/api/documents/create", createDocument)
	http.HandleFunc("/health", healthCheck)
	log.Fatal(http.ListenAndServe(":8080", nil))
}
